// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes memory encodedParameters, address ownedBy) public {
        vm.assume(caller != address(0));
        // Set up the contract: initialize, set roundImplementation and alloSettings, make caller a programOperator
        c.initialize();
        c.updateRoundImplementation(payable(address(1))); // non-zero address
        c.updateAlloSettings(address(2)); // non-zero address
        vm.prank(caller);
        c.create(encodedParameters, ownedBy);
        // After create by caller, owner() should return caller (since create calls initialize via clone, but that's irrelevant; we check the contract c's own owner)
        assertTrue(c.owner() == caller);
    }
}

