pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != address(0));
        // The test does not need to call create(), so we just test the updateRoundImplementation function.
        // We set up a prank as owner to call updateRoundImplementation.
        // For this we need the owner to be the caller. The default owner after initialization is address(this).
        // So we can call from address(this) directly.
        c.updateRoundImplementation(payable(newImpl));
        assertTrue(c.roundImplementation() == newImpl, "roundImplementation not updated");
    }
}

