// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address operator, bytes calldata params, address newOwner) public {
        vm.assume(operator != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != operator);

        // Setup: initialize and add operator
        c.initialize();
        // Use vm.store to set programOperators[operator] = true
        bytes32 slot = keccak256(abi.encode(operator, uint256(2)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Act as operator
        vm.prank(operator);
        // create needs alloSettings and roundImplementation to be set
        // Since they are address(0) initially, this call will revert
        // But the property we're testing is about the onlyOwner modifier
        // We'll use a helper to set them up via owner
        vm.prank(c.owner());
        c.updateAlloSettings(address(0xdead));
        vm.prank(c.owner());
        c.updateRoundImplementation(payable(address(0xbeef)));

        // Now operator calls create - this will succeed in reference, but we test after
        vm.prank(operator);
        c.create(params, operator);

        // Now test the property: owner should be able to transfer ownership
        // In P, this works; in M, it reverts because onlyOwner always passes but transferOwnership checks msg.sender
        // Actually M makes onlyOwner always pass, so transferOwnership should work
        // The difference is: in P, onlyOwner checks owner == msg.sender
        // The property: after create by operator, the ORIGINAL owner (address(this) since we deployed) can transfer
        vm.prank(address(this)); // The original owner from setUp (since initialize sets msg.sender as owner)
        // Actually after setUp, c.owner() is address(0) because constructor doesn't set owner
        // initialize() sets owner to msg.sender
        // So let's redo:
    }

    function testFuzz_ownerCanTransferAfterCreate(address operator, address newOwner) public {
        vm.assume(operator != address(0));
        vm.assume(newOwner != address(0));

        c.initialize();

        // Set up alloSettings and roundImplementation
        vm.prank(address(this));
        c.updateAlloSettings(address(0x1234));
        vm.prank(address(this));
        c.updateRoundImplementation(payable(address(0x5678)));

        // Add operator via vm.store
        bytes32 slot = keccak256(abi.encode(operator, uint256(2)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Operator creates
        vm.prank(operator);
        c.create(abi.encode(0), operator);

        // Now check: owner (address(this)) can transfer ownership
        // In reference P, this succeeds
        // In mutant M, the onlyOwner modifier is broken but the transferOwnership function
        // still has the require(newOwner != address(0)) check, but the problem is different
        // Actually M's onlyOwner never reverts, so it's more permissive, not more restrictive
        // The real difference: in M, anyone can call onlyOwner functions
        // So the property should be: after create, only the REAL owner can transfer
        // In P, only real owner; in M, anyone can
        // Let's test: a non-owner should not be able to transfer in P, but can in M

        vm.prank(operator);
        bool success = false;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // In P, operator is not owner, so it should revert -> success = false
        // In M, onlyOwner passes for anyone, so success = true
        assertTrue(!success, "Operator should not be able to transfer ownership in reference");
    }
}

