import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public {
        c = new C();
        c.initialize();
        initialOwner = address(this);
    }

    function testFuzz_property(bytes calldata encodedParameters, address ownedBy, address programOperator) public {
        vm.assume(programOperator != address(0) && programOperator != address(c) && programOperator != address(this));
        // Make the programOperator a program operator
        vm.prank(programOperator);
        // This call must be made by the owner to add the operator, but we are not the owner in this prank
        // Actually the owner is address(this) from setUp, so we do it directly first
        // Add programOperator as a program operator (requires owner)
        // Since we don't have an addProgramOperator function, we need to manipulate storage directly
        // This is a hack, but we assume the test can set programOperators[programOperator] = true via cheatcode
        // Use vm.store to set the mapping
        // mapping key = keccak256(abi.encode(programOperator, uint256(7))) where 7 is the slot for programOperators mapping
        // But simpler: just assume the caller of create is a program operator by pranking before
        // Actually we can call c.create() only through onlyProgramOperator, so we need programOperator to be set as such
        // For the purpose of the test, we can use vm.store to set the mapping directly
        bytes32 slot = keccak256(abi.encode(programOperator, uint256(7)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Now prank as programOperator
        vm.startPrank(programOperator);
        // Ensure c has enough balance if needed (not needed)
