pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Only test when caller is the owner (the deployer)
        vm.assume(caller == c.owner());
        // Ensure newOwner is not zero address to avoid revert
        vm.assume(newOwner != address(0));

        address ownerBefore = c.owner();

        vm.prank(caller);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("transferOwnership(address)", newOwner)
        );

        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == ownerBefore);
        }
    }
