pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newRoundImpl, address newAlloSettings, bytes memory encodedParameters, address ownedBy) public {
        // Bound inputs to avoid out-of-gas / revert issues
        vm.assume(caller != address(0));
        vm.assume(newRoundImpl != address(0));
        vm.assume(newAlloSettings != address(0));
        vm.assume(ownedBy != address(0) && ownedBy != address(c));

        // Set up: initialize if needed, set owner to caller, configure round and alloSettings
        // Since initialize is initializer, only call if not initialized
        if (c.owner() == address(0)) {
            c.initialize();
        }
        // Transfer ownership to caller if not already
        if (c.owner() != caller) {
            vm.prank(c.owner());
            c.transferOwnership(caller);
        }
        // Ensure caller is owner
        vm.assume(c.owner() == caller);

        // Configure inputs via the owner
        vm.prank(caller);
        c.updateRoundImplementation(payable(newRoundImpl));
        vm.prank(caller);
        c.updateAlloSettings(newAlloSettings);

        // Record owner before create
        address ownerBefore = c.owner();
        vm.prank(caller);
        c.create(encodedParameters, ownedBy);
        // After create, owner must be unchanged
        assertTrue(c.owner() == ownerBefore);
    }
}

